import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def load_factors():
    try:
        return json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 0.5) / len(valid)
    return out


def normalize_weights(raw):
    # Soft 2%-14% bounds retain diversification for this 15-asset universe.
    w = {s: max(float(raw.get(s, 1e-8)), 1e-8) for s in UNIVERSE}
    for _ in range(50):
        w = {s: x / sum(w.values()) for s, x in w.items()}
        changed = False
        for s in UNIVERSE:
            if w[s] < 0.02:
                w[s] = 0.02; changed = True
            elif w[s] > 0.14:
                w[s] = 0.14; changed = True
        if not changed:
            break
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    factors = load_factors()
    if not factors:
        return

    feat, vol, stamps = {}, {}, {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 110:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)[:-1]  # completed bars only
        if len(close) < 100 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v10, v20, v30, v40 = [max(np.std(ret[-n:]), 0.008) for n in (10, 20, 30, 40)]
        negative = ret[-40:][ret[-40:] < 0]
        downside = max(np.std(negative) if len(negative) > 1 else v40, 0.008)
        stress = max(0.0, v40 / max(np.std(ret[-100:]), 0.008) - 1.0)
        feat[symbol] = {
            "breadth": 0.6 * (close[-1] / close[-21] - 1) / v20 + 0.4 * (close[-1] / close[-6] - 1) / v10,
            "asym_reversal": -(close[-1] / close[-3] - 1) / v10,
            "stress_trend": (close[-1] / close[-31] - 1) / v30 / (1 + stress),
            "risk_momentum": (close[-1] / close[-21] - 1) / max(v20, downside),
            "trend_accel": (close[-1] / close[-11] - 1) / v10 - (close[-11] / close[-31] - 1) / v20,
        }
        vol[symbol] = max(np.std(ret[-25:]), 0.008)
        stamps[symbol] = str(df.iloc[-1]["date"])

    stamp = max(stamps.values())
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            return

    feature_map = {
        "miner_3_20280619_trend_acceleration_risk_adjusted": "trend_accel",
        "miner_3_20270830_downside_sharpe40": "risk_momentum",
        "miner_1_20270830_stress_conditional_trend": "stress_trend",
        "miner_3_20261130_asymmetric_volatility_reversal_2d_revalidated": "asym_reversal",
        "miner_1_20270827_breadth_defensive_trend": "breadth",
    }
    score = {s: 0.5 for s in UNIVERSE}
    for factor in factors:
        key = feature_map.get(factor.get("factor_id"))
        if key is None:
            continue
        direction = float(factor.get("direction", 1))
        ranks = cross_rank({s: direction * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += float(factor.get("weight", 0.0)) * (ranks[s] - 0.5)

    # High-risk sideways/bearish posture: defensive tradable assets, never cash.
    spx_bear = feat["SPX"]["breadth"] < 0 and feat["SPX"]["stress_trend"] < 0
    stressed = False
    vix = get_index_daily_data(symbol="VIX", days=70)
    if vix is not None and len(vix) > 35:
        x = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        stressed = len(x) > 30 and x[-1] > np.mean(x[-30:]) + 0.5 * np.std(x[-30:])
    if spx_bear or stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.06

    avg_inverse_vol = np.mean([1.0 / vol[s] for s in UNIVERSE])
    raw = {s: max(score[s], 0.05) * (0.78 + 0.22 * (1.0 / vol[s]) / avg_inverse_vol) for s in UNIVERSE}
    mean_score = np.mean(list(score.values()))
    sd_score = max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    target = normalize_weights(raw)
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f["factor_id"] for f in factors], horizon_days=10)
    last_decision = stamp


strategy = cross_asset_strategy

