    except Exception:
        return []


def rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return out
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 0.5) / len(valid)
    return out


def bounded_weights(raw):
    # Full investment, modest 2%-14% bounds; no cash sleeve.
    w = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    for _ in range(100):
        total = sum(w.values())
        w = {s: x / total for s, x in w.items()}
        changed = False
        for s in UNIVERSE:
            if w[s] < 0.02:
                w[s] = 0.02; changed = True
            elif w[s] > 0.14:
                w[s] = 0.14; changed = True
        if not changed:
            break
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    factors = load_factors()
    if not factors:
        return

    feat, vol, dates = {}, {}, {}
