            return
        r = close[1:] / close[:-1] - 1.0
        def sd(n): return max(float(np.std(r[-n:])), 0.008)
        v10, v20, v30, v40 = sd(10), sd(20), sd(30), sd(40)
        neg40 = r[-40:][r[-40:] < 0]
