        consistency = float(np.mean(r[-60:] > 0) - 0.5)
        # Six robust proxies corresponding exactly to the current ensemble.
        feat[symbol] = {
            "breadth_defensive": 0.60 * (close[-1] / close[-21] - 1) / v20 + 0.40 * (close[-1] / close[-6] - 1) / v10,
            "downside_sharpe": (close[-1] / close[-41] - 1) / down40,
            "stress_trend": (close[-1] / close[-31] - 1) / v30 / (1 + stress),
            "asym_reversal": -(close[-1] / close[-3] - 1) / v10,
            # Dispersion reversal: recent relative shock versus its own longer move.
            "dispersion_reversal": -((close[-1] / close[-6] - 1) / v10) + 0.5 * ((close[-1] / close[-21] - 1) / v20),
            "breadth_stability": ((close[-1] / close[-61] - 1) / down60) * (0.5 + consistency),
