        "miner_3_20270830_downside_sharpe40": "downside_sharpe",
        "miner_1_20270830_stress_conditional_trend": "stress_trend",
        "miner_3_20261130_asymmetric_volatility_reversal_2d_revalidated": "asym_reversal",
        "miner_2_20270506_dispersion_reversal": "dispersion_reversal",
        "miner_1_20280814_trend_breadth_stability60_downside": "breadth_stability",
    }
