    inv_avg = np.mean([1.0 / vol[s] for s in UNIVERSE])
    raw = {s: max(score[s], 0.05) * (0.78 + 0.22 * (1.0 / vol[s]) / inv_avg) for s in UNIVERSE}
    mean, stdev = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mean) / stdev) for s in UNIVERSE}
    target = bounded_weights(raw)
    rebalance_to_weights(target, forecast_returns=forecast,
