ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs[:10] if fs else []
    except Exception:
        return []


def cross_rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def full_investment(raw):
    # Defensive diversification bounds, then exact normalization.
    w = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    for _ in range(20):
        z = sum(w.values())
        w = {s: min(0.14, max(0.02, x / z)) for s, x in w.items()}
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    factors = load_factors()
    if not factors:
        return
    factor_ids = [f["factor_id"] for f in factors]
    factor_weights = {f["factor_id"]: float(f.get("weight", 0.0)) for f in factors}
    directions = {f["factor_id"]: float(f.get("direction", 1)) for f in factors}
    required = set(factor_ids)
    data, vols = {}, {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        # Exclude the current incomplete bar: all signals are lagged.
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 80 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.008)
        v40 = max(float(np.std(r[-40:])), 0.008)
        neg20, neg40 = r[-20:][r[-20:] < 0], r[-40:][r[-40:] < 0]
        d20 = max(float(np.sqrt(np.mean(neg20 ** 2))) if len(neg20) else v20, 0.008)
        d40 = max(float(np.sqrt(np.mean(neg40 ** 2))) if len(neg40) else v40, 0.008)
        ret20, ret40 = c[-1] / c[-21] - 1, c[-1] / c[-41] - 1
        data[s] = {
            "trend": ret20 / v20,
            "down20": ret20 / (d20 * np.sqrt(252) + 0.01),
            "down40": ret40 / (d40 * np.sqrt(252) + 0.01),
            "consistency": float(np.mean(r[-40:])) / v40,
            "efficiency": ret40 / (float(np.sum(np.abs(r[-40:]))) + 0.01),
        }
        vols[s] = max(float(np.std(r[-25:])), 0.008)
        stamp = str(df.iloc[-1]["date"])
    if last_decision is not None and (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
        return

    breadth = float(np.mean([data[s]["trend"] > 0 for s in UNIVERSE]))
