    sd_score = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_decision = stamp


strategy = cross_asset_strategy
if __name__ == "__main__":
    pass

