import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def load_factors():
    try:
        return json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def xrank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n
    return out


def bounded_weights(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    # A modest floor and cap are appropriate for a 15-asset, full-investment book.
    for _ in range(30):
        z = sum(w.values())
        w = {s: min(0.14, max(0.02, v / z)) for s, v in w.items()}
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    factors = load_factors()
    if not factors or len(factors) > 10:
        return
    factor_ids = [f["factor_id"] for f in factors]
    weights = {f["factor_id"]: float(f["weight"]) for f in factors}
    directions = {f["factor_id"]: float(f.get("direction", 1)) for f in factors}

    values, vol = {}, {}
    stamp = None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)
        # Do not use an in-progress bar when the data provider exposes one.
        close = close[:-1]
        if len(close) < 80 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20 = max(float(np.std(ret[-20:])), 0.008)
        v40 = max(float(np.std(ret[-40:])), 0.008)
        neg20 = ret[-20:][ret[-20:] < 0]
        neg40 = ret[-40:][ret[-40:] < 0]
        d20 = max(float(np.sqrt(np.mean(neg20 ** 2))) if len(neg20) else v20, 0.008)
        d40 = max(float(np.sqrt(np.mean(neg40 ** 2))) if len(neg40) else v40, 0.008)
        r20 = close[-1] / close[-21] - 1.0
        r40 = close[-1] / close[-41] - 1.0
        values[symbol] = {
            "trend": r20 / v20,
            "down20": r20 / (d20 * np.sqrt(252) + 0.01),
            "down40": r40 / (d40 * np.sqrt(252) + 0.01),
            "efficiency": r40 / (float(np.sum(np.abs(ret[-40:]))) + 0.01),
            # Positive reversal score favors assets that recently lagged.
            "reversal": -r20,
            "asset_vol": v20,
        }
        vol[symbol] = v40
        stamp = str(df.iloc[-1]["date"])

    if last_decision is not None and (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
        return

    breadth = np.mean([values[s]["trend"] > 0 for s in UNIVERSE])
    weak = breadth < 0.45
    dispersion = float(np.std([values[s]["asset_vol"] for s in UNIVERSE]))
    # Conditional reversal: only activate in an intermediate, not panic, dispersion state.
    vols = np.array([values[s]["asset_vol"] for s in UNIVERSE])
    intermediate = bool(np.quantile(vols, 0.25) <= dispersion <= np.quantile(vols, 0.75))
    defensive_mean = np.mean([values[s]["trend"] for s in DEFENSIVE])

    signals = {s: {} for s in UNIVERSE}
    for s in UNIVERSE:
        signals[s]["miner_1_20270827_breadth_defensive_trend"] = (
            0.35 * values[s]["trend"] + 0.65 * defensive_mean
            if weak and s in DEFENSIVE else values[s]["trend"]
        )
        signals[s]["miner_2_20281023_downside_sharpe20"] = values[s]["down20"]
        signals[s]["miner_3_20290730_dispersion_bucket_reversal20"] = values[s]["reversal"] if intermediate else 0.0
        signals[s]["miner_3_20270827_path_efficiency40"] = values[s]["efficiency"]
        signals[s]["miner_3_20270830_downside_sharpe40"] = values[s]["down40"]

    score = {s: 0.5 for s in UNIVERSE}
    for fid in factor_ids:
        ranked = xrank({s: directions[fid] * signals[s].get(fid, 0.0) for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (ranked[s] - 0.5)
    if weak:
        for s in DEFENSIVE:
            score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.06

    inv_mean = np.mean([1.0 / vol[s] for s in UNIVERSE])
    raw = {s: max(score[s], 0.05) * (0.78 + 0.22 * (1.0 / vol[s]) / inv_mean) for s in UNIVERSE}
    target = bounded_weights(raw)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_decision = stamp


strategy = cross_asset_strategy
if __name__ == "__main__":
    pass

