import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factor_ensemble.json"
last_stamp = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n
    return out


def project(raw):
    # Full-investment long-only portfolio; fractional quantities are handled downstream.
    w = {s: max(float(raw[s]), 1e-9) for s in UNIVERSE}
    for _ in range(100):
        w = {s: min(0.14, max(0.02, v)) for s, v in w.items()}
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < 0.14 - 1e-10) or (gap < 0 and w[s] > 0.02 + 1e-10)]
        if not free:
            break
        add = gap / len(free)
        for s in free:
            w[s] += add
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_stamp
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    fw = {str(f["factor_id"]): float(f["weight"]) for f in ensemble}
    direction = {str(f["factor_id"]): float(f.get("direction", 1)) for f in ensemble}
    d = {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 80 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.008)
        v40 = max(float(np.std(r[-40:])), 0.008)
        neg20 = r[-20:][r[-20:] < 0]
        neg40 = r[-40:][r[-40:] < 0]
        dn20 = max(float(np.sqrt(np.mean(neg20**2))) if len(neg20) else v20, 0.008)
        dn40 = max(float(np.sqrt(np.mean(neg40**2))) if len(neg40) else v40, 0.008)
        r20 = c[-1] / c[-21] - 1.0
        r40 = c[-1] / c[-41] - 1.0
        d[s] = {"trend": r20 / v20, "down20": r20 / (dn20*np.sqrt(252)+0.01),
                "relative": (r20, v40), "eff40": r40/(np.sum(np.abs(r[-40:]))+0.01),
                "down40": r40/(dn40*np.sqrt(252)+0.01), "vol": v40}
        stamp = str(df.iloc[-1]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_stamp))/np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass
    breadth = np.mean([d[s]["trend"] > 0 for s in UNIVERSE])
    weak = breadth < 0.45
    deftrend = np.mean([d[s]["trend"] for s in DEFENSIVE])
    med = np.median([d[s]["relative"][0] for s in UNIVERSE])
    signals = {s: {
        "miner_1_20270827_breadth_defensive_trend": (0.35*d[s]["trend"]+0.65*deftrend if weak and s in DEFENSIVE else d[s]["trend"]),
        "miner_2_20281023_downside_sharpe20": d[s]["down20"],
        "miner_1_20280717_breadth_gated_relative_trend20_vol40": ((d[s]["relative"][0]-med)/(d[s]["relative"][1]*np.sqrt(20)+0.01)) * (-1 if breadth < 0.4 else 1),
        "miner_3_20270827_path_efficiency40": d[s]["eff40"],
        "miner_3_20270830_downside_sharpe40": d[s]["down40"]} for s in UNIVERSE}
    score = {s: 0.5 for s in UNIVERSE}
    for fid in factor_ids:
        rr = ranks({s: direction[fid]*signals[s][fid] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += fw[fid]*(rr[s]-0.5)
    if weak:
        for s in DEFENSIVE: score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"): score[s] -= 0.06
    inv = {s: 1.0/d[s]["vol"] for s in UNIVERSE}
    avg = np.mean(list(inv.values()))
    target = project({s: max(score[s], 0.05)*(0.78+0.22*inv[s]/avg) for s in UNIVERSE})
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(0.01*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_stamp = stamp

