UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factor_ensemble.json"
last_stamp = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def project(raw):
    w = {s: max(float(raw[s]), 1e-9) for s in UNIVERSE}
    for _ in range(100):
        w = {s: min(0.14, max(0.02, v)) for s, v in w.items()}
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < 0.14 - 1e-10) or (gap < 0 and w[s] > 0.02 + 1e-10)]
        if not free:
            break
        for s in free:
            w[s] += gap / len(free)
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_stamp
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    fw = {str(f["factor_id"]): float(f["weight"]) for f in ensemble}
    direction = {str(f["factor_id"]): float(f.get("direction", 1)) for f in ensemble}
    d, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 80 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20, v40 = max(float(np.std(r[-20:])), .008), max(float(np.std(r[-40:])), .008)
        n20, n40 = r[-20:][r[-20:] < 0], r[-40:][r[-40:] < 0]
        dn20 = max(float(np.sqrt(np.mean(n20**2))) if len(n20) else v20, .008)
        dn40 = max(float(np.sqrt(np.mean(n40**2))) if len(n40) else v40, .008)
        r20, r40 = c[-1] / c[-21] - 1, c[-1] / c[-41] - 1
        d[s] = {"trend": r20 / v20, "down20": r20 / (dn20*np.sqrt(252)+.01),
                "relative": r20, "eff40": r40/(np.sum(np.abs(r[-40:]))+.01),
                "down40": r40/(dn40*np.sqrt(252)+.01), "vol": v40}
        stamp = str(df.iloc[-1]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_stamp))/np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass
    breadth = np.mean([d[s]["trend"] > 0 for s in UNIVERSE])
    weak = breadth < .45
    deftrend = np.mean([d[s]["trend"] for s in DEFENSIVE])
    med = np.median([d[s]["relative"] for s in UNIVERSE])
    signals = {s: {
        "miner_1_20270827_breadth_defensive_trend": (0.35*d[s]["trend"] + .65*deftrend if weak and s in DEFENSIVE else d[s]["trend"]),
        "miner_2_20281023_downside_sharpe20": d[s]["down20"],
        "miner_1_20280717_breadth_gated_relative_trend20_vol40": (d[s]["relative"]-med)/(d[s]["vol"]*np.sqrt(20)+.01),
        "miner_3_20270827_path_efficiency40": d[s]["eff40"],
        "miner_3_20270830_downside_sharpe40": d[s]["down40"]} for s in UNIVERSE}
    score = {s: .5 for s in UNIVERSE}
    for fid in factor_ids:
        rr = ranks({s: direction[fid] * signals[s][fid] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += fw[fid] * (rr[s] - .5)
    if weak:
        for s in DEFENSIVE: score[s] += .10
        for s in ("BTC", "ETH", "WTI"): score[s] -= .06
    inv = {s: 1 / d[s]["vol"] for s in UNIVERSE}
    avg = np.mean(list(inv.values()))
    target = project({s: max(score[s], .05) * (.78 + .22*inv[s]/avg) for s in UNIVERSE})
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-mean)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_stamp = stamp

# factor ensemble synchronized 2029-10-08; all targets are full-investment and long-only.

# End of strategy hook.

