import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 0.5) / len(valid)
    return out


def bounded_weights(raw):
    # Full investment, diversified 2%-14% bounds, with fractional quantities downstream.
    w = {s: max(0.02, min(0.14, float(raw[s]))) for s in UNIVERSE}
    for _ in range(20):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < .14) or (gap < 0 and w[s] > .02)]
        if not free or abs(gap) < 1e-10:
            break
        for s in free:
            w[s] += gap / len(free)
            w[s] = max(.02, min(.14, w[s]))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_stamp
    ensemble = load_ensemble()
    if not ensemble:
        return
    ids = [str(x["factor_id"]) for x in ensemble]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ensemble}
    data, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)[:-1]  # previous completed session only
        if len(close) < 80 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20 = max(float(np.std(ret[-20:])), .008)
        v40 = max(float(np.std(ret[-40:])), .008)
        neg20, neg40 = ret[-20:][ret[-20:] < 0], ret[-40:][ret[-40:] < 0]
        dn20 = max(float(np.sqrt(np.mean(neg20**2))) if len(neg20) else v20, .008)
        dn40 = max(float(np.sqrt(np.mean(neg40**2))) if len(neg40) else v40, .008)
        r20, r40 = close[-1] / close[-21] - 1, close[-1] / close[-41] - 1
        peak = np.maximum.accumulate(close[-60:])
        dd = close[-60:] / peak - 1.0
        # Recovery/drawdown acceleration: improving recent drawdown versus prior window.
        recovery = float(np.mean(dd[-10:]) - np.mean(dd[-30:-20]))
        data[symbol] = {"trend": r20 / v20, "down20": r20 / (dn20*np.sqrt(252)+.01),
                        "relative": r20, "eff40": r40 / (np.sum(np.abs(ret[-40:]))+.01),
                        "down40": r40 / (dn40*np.sqrt(252)+.01), "vol": v40,
                        "recovery": recovery}
        stamp = str(df.iloc[-1]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_stamp)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass
    breadth = np.mean([data[s]["trend"] > 0 for s in UNIVERSE])
    weak = breadth < .45
    defensive_trend = np.mean([data[s]["trend"] for s in DEFENSIVE])
    median_relative = np.median([data[s]["relative"] for s in UNIVERSE])
    signals = {s: {
        "miner_1_20270827_breadth_defensive_trend": (.35*data[s]["trend"] + .65*defensive_trend if weak and s in DEFENSIVE else data[s]["trend"]),
        "miner_2_20281023_downside_sharpe20": data[s]["down20"],
        "miner_1_20280717_breadth_gated_relative_trend20_vol40": (data[s]["relative"]-median_relative)/(data[s]["vol"]*np.sqrt(20)+.01),
        "miner_3_20270827_path_efficiency40": data[s]["eff40"],
        "miner_3_20270830_downside_sharpe40": data[s]["down40"],
        "miner_1_20291022_drawdown_acceleration": data[s]["recovery"]
    } for s in UNIVERSE}
    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        ranks = rank({s: directions[fid] * signals[s].get(fid, 0.0) for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (ranks[s] - .5)
    if weak:
        for s in DEFENSIVE:
            score[s] += .10
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06
    inv = {s: 1.0 / data[s]["vol"] for s in UNIVERSE}
    avg_inv = np.mean(list(inv.values()))
    target = bounded_weights({s: max(score[s], .05) * (.78 + .22*inv[s]/avg_inv) for s in UNIVERSE})
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_stamp = stamp

