import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(vals):
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n if n else 0.5
    return out


def bounded(raw):
    lo, hi = 0.02, 0.16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(30):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < hi) or (gap < 0 and w[s] > lo)]
        if not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_stamp
    ens = ensemble()
    if not ens or len(ens) > 10:
        return
    ids = [str(x["factor_id"]) for x in ens]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data = {}
