            "residual": -r20 / v20,
            "vixrev": -r20 / v20,
            "vol": v40,
        }
        stamp = str(df.iloc[-2]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_stamp)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass
    breadth = float(np.mean([data[s]["trend"] > 0 for s in UNIVERSE]))
