        "miner_2_20281023_downside_sharpe20": data[s]["downside"],
        "miner_1_20291022_drawdown_acceleration": data[s]["recovery"],
        "miner_3_20270827_path_efficiency40": data[s]["path"],
        "miner_1_20290813_residual_reversal20": data[s]["residual"] - median_resid,
        "miner_1_20281120_vix_gated_reversal20": data[s]["vixrev"] * (1.25 if breadth < .55 else .75),
    } for s in UNIVERSE}
    score = {s: 0.5 for s in UNIVERSE}
    for fid in ids:
        rr = ranks({s: directions[fid] * signal[s][fid] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (rr[s] - 0.5)
    if breadth < .45:
        for s in DEFENSIVE:
            score[s] += .08
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .04
    inv = {s: 1.0 / data[s]["vol"] for s in UNIVERSE}
    mean_inv = float(np.mean(list(inv.values())))
    raw = {s: max(.04, score[s]) * (.85 + .15 * inv[s] / mean_inv) for s in UNIVERSE}
    target = bounded(raw)
    avg = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(.01 * (score[s] - avg) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_stamp = stamp

