DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def get_ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank(values):
    finite = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(finite)
    for i, (s, _) in enumerate(finite):
        out[s] = (i + 0.5) / n
    return out


def normalize(raw):
    # Complete, long-only, full-investment vector with sensible cross-asset bounds.
    lo, hi = 0.02, 0.16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(50):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-12:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < hi) or (gap < 0 and w[s] > lo)]
        if not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_stamp
    ens = get_ensemble()
    if not ens or len(ens) > 10:
        return
    ids = [str(x["factor_id"]) for x in ens]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data, stamp = {}, None
    for sym in UNIVERSE:
        df = get_stock_daily_data(symbol=sym, days=280)
        if df is None or len(df) < 80:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)[:-1]
        if len(close) < 65 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20 = max(float(np.std(ret[-20:])), .008)
        v40 = max(float(np.std(ret[-40:])), .008)
        downside = max(float(np.sqrt(np.mean(np.minimum(ret[-20:], 0.0) ** 2))), .008)
        r20, r40 = close[-1] / close[-21] - 1, close[-1] / close[-41] - 1
        consistency = float(np.mean(ret[-40:] > 0))
        data[sym] = {"trend": r20 / v40, "down": r20 / (downside * np.sqrt(20) + .01),
                     "path": r40 / v40 * (.5 + consistency), "vol": v40,
                     "rev20": -r20 / v20, "rev30": -(close[-1] / close[-31] - 1) / max(float(np.std(ret[-30:])), .008)}
        stamp = str(df.iloc[-2]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_stamp)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass
    breadth = float(np.mean([data[s]["trend"] > 0 for s in UNIVERSE]))
    defensive_trend = float(np.mean([data[s]["trend"] for s in DEFENSIVE]))
    signals = {}
    for s in UNIVERSE:
        trend = data[s]["trend"]
        signals[s] = {
            "miner_1_20270827_breadth_defensive_trend": (0.35 * trend + 0.65 * defensive_trend) if breadth < .45 and s in DEFENSIVE else trend,
            "miner_2_20281023_downside_sharpe20": data[s]["down"],
            "miner_3_20270827_path_efficiency40": data[s]["path"],
            "miner_1_20280717_breadth_gated_relative_trend20_vol40": trend * (.7 + .6 * breadth),
            "miner_1_20281120_vix_gated_reversal20": data[s]["rev20"] * (1.2 if breadth < .55 else .7),
            "miner_1_20300225_highdisp_residual_reversal30": data[s]["rev30"]
        }
    score = {s: 0.5 for s in UNIVERSE}
    for fid in ids:
        rr = rank({s: directions[fid] * signals[s][fid] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (rr[s] - .5)
    if breadth < .45:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv_mean = np.mean([1.0 / data[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15 * (1.0 / data[s]["vol"]) / inv_mean) for s in UNIVERSE}
    target = normalize(raw)
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - avg) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_stamp = stamp

