DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def ensemble():
    try:
        return json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(vals):
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def bounded_weights(raw):
    lo, hi = 0.02, 0.16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(40):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-11:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < hi) or (gap < 0 and w[s] > lo)]
        if not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
