import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None

def load_ensemble():
    try:
        return json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []

def rank(vals):
    valid = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + .5) / len(valid)
    return out

def bounded(raw):
    lo, hi = .02, .16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-12: break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < hi) or (gap < 0 and w[s] > lo)]
        if not free: break
        for s in free: w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_stamp
    ens = load_ensemble()
    if not ens: return
    ids = [str(x["factor_id"]) for x in ens]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 90: return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]  # only completed bars
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0): return
        r = c[1:] / c[:-1] - 1
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        d20 = max(float(np.sqrt(np.mean(np.minimum(r[-20:], 0.) ** 2))), .008)
        d60 = max(float(np.sqrt(np.mean(np.minimum(r[-60:], 0.) ** 2))), .008)
        r20, r30, r40 = c[-1]/c[-21]-1, c[-1]/c[-31]-1, c[-1]/c[-41]-1
        eff = r40 / max(float(np.sum(np.abs(r[-40:]))), .01)
        lo, hi = np.min(c[-20:]), np.max(c[-20:])
        range_impulse = (c[-1] - lo) / max(hi-lo, 1e-9) - .5
        data[s] = {"trend": r20/v40, "down": r20/(d20*np.sqrt(20)+.01),
                   "sortino": r30/(d60*np.sqrt(30)+.01), "path": eff,
                   "rev": -r20/v20, "range": range_impulse, "vol": v40}
        stamp = str(df.iloc[-2]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_stamp))/np.timedelta64(1,"D") < 10: return
        except Exception: pass
    breadth = float(np.mean([data[s]["trend"] > 0 for s in UNIVERSE]))
    mean_vol = float(np.mean([data[s]["vol"] for s in UNIVERSE]))
    defensive_mean = float(np.mean([data[s]["trend"] for s in DEFENSIVE]))
    sig = {s: {} for s in UNIVERSE}
    for s in UNIVERSE:
        trend = data[s]["trend"]
        sig[s]["miner_1_20270827_breadth_defensive_trend"] = trend if breadth >= .45 else (.35*trend + .65*defensive_mean if s in DEFENSIVE else trend)
