        sig[s]["miner_1_20281120_vix_gated_reversal20"] = data[s]["rev"] * (1.25 if mean_vol > .018 else .55)
        sig[s]["miner_3_20270604_risk_adjusted_20d_momentum"] = trend
        sig[s]["miner_1_20300617_downside_sortino30_60"] = data[s]["sortino"]
        sig[s]["miner_3_20270827_path_efficiency40"] = data[s]["path"]
        sig[s]["miner_2_20300422_range_position_impulse"] = data[s]["range"]
    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        rr = rank({s: directions[fid] * sig[s].get(fid, 0.) for s in UNIVERSE})
        for s in UNIVERSE: score[s] += weights[fid] * (rr[s]-.5)
    if breadth < .45:
        for s in DEFENSIVE: score[s] += .06
