DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None

def load_ensemble():
    try:
        return json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []

def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + .5) / max(len(good), 1)
    return out

def bound_weights(raw):
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(60):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10: break
        free = [s for s in UNIVERSE if (.02 < w[s] < .16) or (gap > 0 and w[s] < .16) or (gap < 0 and w[s] > .02)]
        if not free: break
        for s in free: w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_stamp
    ens = load_ensemble()
    if not ens or len(ens) > 10: return
    ids = [str(x["factor_id"]) for x in ens]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data = {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 90: return
        df = df.sort_values("date")
        # The final row is the possibly incomplete current bar; use only completed bars.
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0): return
        r = c[1:] / c[:-1] - 1.0
        r20, r40 = c[-1] / c[-21] - 1, c[-1] / c[-41] - 1
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
        downside = max(np.sqrt(np.mean(np.minimum(r[-20:], 0)**2)), .008)
        path40 = r40 / max(np.sum(np.abs(r[-40:])), .02)
        lo, hi = np.min(c[-41:]), np.max(c[-41:])
        range_pos = (c[-1] - lo) / max(hi - lo, 1e-9)
        # Reversal is deliberately stress-gated and uses lagged prices only.
        data[s] = {"r20": r20, "v20": v20, "v40": v40,
                   "breadth": np.mean(r[-20:] > 0), "rev": -r20 / v20,
                   "downsharpe": r20 / (downside * np.sqrt(20) + .01),
                   "path40": path40, "rangeimp": (0.5 - range_pos) * abs(r20) / v20}
        stamp = str(df.iloc[-2]["date"])
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_stamp)) / np.timedelta64(1, "D") < 10: return
        except Exception: pass
    avgvol = float(np.mean([data[s]["v40"] for s in UNIVERSE]))
    breadth = float(np.mean([data[s]["r20"] > 0 for s in UNIVERSE]))
    stress = avgvol > .018 or breadth < .45
    signal = {}
    for s, d in data.items():
        signal[s] = {
            "miner_1_20281120_vix_gated_reversal20": d["rev"] * (1.35 if stress else .55),
            "miner_1_20270827_breadth_defensive_trend": d["r20"] / d["v40"] * (.7 + .6*d["breadth"]),
            "miner_2_20281023_downside_sharpe20": d["downsharpe"],
            "miner_3_20270827_path_efficiency40": d["path40"],
            "miner_2_20300422_range_position_impulse": d["rangeimp"]}
    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        rr = ranks({s: directions[fid] * signal[s].get(fid, 0.0) for s in UNIVERSE})
        for s in UNIVERSE: score[s] += weights[fid] * (rr[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .08
        for s in ("BTC", "ETH", "WTI"): score[s] -= .035
    invmean = np.mean([1/d["v40"] for d in data.values()])
    raw = {s: max(.04, score[s]) * (.85 + .15*(1/data[s]["v40"])/invmean) for s in UNIVERSE}
    target = bound_weights(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_stamp = stamp

