UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def load_ensemble():
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return selected[:10]
    except Exception:
        return []


def rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = max(1, len(valid))
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 0.5) / n
    return out


def bounded(raw):
    w = {s: min(0.16, max(0.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if (gap > 0 and w[s] < 0.16) or (gap < 0 and w[s] > 0.02)]
        if not free:
            break
        for s in free:
            w[s] = min(0.16, max(0.02, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    ensemble = load_ensemble()
    if not ensemble or len(ensemble) > 10:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ensemble}
    feature_key = {
        "miner_1_20270827_breadth_defensive_trend": "trend",
        "miner_2_20281023_downside_sharpe20": "down",
        "miner_3_20270827_path_efficiency40": "path",
        "miner_1_20281120_vix_gated_reversal20": "vixrev",
        "miner_3_20270503_vix_stress_reversal": "stressrev",
    }
    if any(fid not in feature_key for fid in factor_ids):
        return

    feat, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=280)
        if df is None or len(df) < 90:
            return
        df = df.sort_values("date")
        # Exclude the latest row so the signal and forecast are lagged.
        close = np.asarray(df["close"], dtype=float)[:-1]
        if len(close) < 65 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20 = max(float(np.std(ret[-20:])), 0.008)
        v40 = max(float(np.std(ret[-40:])), 0.008)
        downside = max(float(np.sqrt(np.mean(np.minimum(ret[-20:], 0.0) ** 2))), 0.008)
        r20 = close[-1] / close[-21] - 1.0
        r40 = close[-1] / close[-41] - 1.0
        feat[symbol] = {
            "trend": r20 / v40 * (0.7 + 0.6 * float(np.mean(ret[-20:] > 0))),
            "down": r20 / (downside * np.sqrt(20.0) + 0.01),
            "path": r40 / max(float(np.sum(np.abs(ret[-40:])), 0.02), 0.02),
            "vixrev": -r20 / v20,
            "stressrev": -(close[-1] / close[-11] - 1.0) / v20,
            "vol": v40,
        }
        stamp = str(df.iloc[-2]["date"])

    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            pass

    score = {s: 0.5 for s in UNIVERSE}
    for fid in factor_ids:
        values = {s: directions[fid] * feat[s][feature_key[fid]] for s in UNIVERSE}
        r = rank(values)
        for s in UNIVERSE:
            score[s] += factor_weights[fid] * (r[s] - 0.5)

    mean_vol = float(np.mean([feat[s]["vol"] for s in UNIVERSE]))
    breadth = float(np.mean([feat[s]["trend"] > 0 for s in UNIVERSE]))
    if mean_vol > 0.018 or breadth < 0.45:
        for s in DEFENSIVE:
            score[s] += 0.08
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.035

    inv_mean = float(np.mean([1.0 / feat[s]["vol"] for s in UNIVERSE]))
    raw = {s: max(0.04, score[s]) * (0.85 + 0.15 * (1.0 / feat[s]["vol"]) / inv_mean) for s in UNIVERSE}
    target = bounded(raw)
    avg = float(np.mean(list(score.values())))
    std = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.01 * (score[s] - avg) / std) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_decision = stamp

