import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None

def _ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []

def _rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + .5) / max(n, 1)
    return out

def _weights(raw):
    # Sensible 15-asset bounds, followed by exact normalization.
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-11: break
        free = [s for s in UNIVERSE if (.02 < w[s] < .16) or (gap > 0 and w[s] < .16) or (gap < 0 and w[s] > .02)]
        if not free: break
        for s in free: w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_decision
    ens = _ensemble()
    if not ens or len(ens) > 10: return
    ids = [str(x["factor_id"]) for x in ens]
    allowed = {"miner_1_20270827_breadth_defensive_trend", "miner_1_20300617_downside_sortino30_60", "miner_1_20300715_path_efficiency20", "miner_1_20281120_vix_gated_reversal20", "miner_3_20270503_vix_stress_reversal"}
    if any(i not in allowed for i in ids): return
    weights = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 90: return
        df = df.sort_values("date")
        # The last row can be today's incomplete observation; use completed data only.
        c = np.asarray(df["close"], float)[:-1]
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0): return
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        downside = max(float(np.std(np.minimum(r[-60:], 0.0))), .008)
        r10, r20, r30 = c[-1]/c[-11]-1, c[-1]/c[-21]-1, c[-1]/c[-31]-1
        path20 = max(float(np.sum(np.abs(r[-20:]))), .02)
        data[s] = {"trend": r20/(v40+.01), "down": r30/(np.sqrt(60)*downside+.01), "path": r20/path20,
                   "vixrev": -r20/v40, "stressrev": -r10/v20, "vol": v40}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_decision))/np.timedelta64(1,"D") < 10: return
        except Exception: pass
    # Observation-only VIX gates reversal factors; missing VIX simply deactivates them.
    vix = get_index_daily_data(symbol="VIX", days=80)
    vix_on = False
    if vix is not None and len(vix) >= 61:
        vc = np.asarray(vix.sort_values("date")["close"], float)[:-1]
        if len(vc) >= 61 and np.isfinite(vc[-1]):
            vix_on = vc[-1] < float(np.median(vc[-60:]))
            stress = (vc[-1]-np.mean(vc[-60:]))/max(np.std(vc[-60:]), 1e-8) > .75
        else: stress = False
    else: stress = False
    score = {s: .5 for s in UNIVERSE}
    for f in ens:
        fid = str(f["factor_id"]); vals = {s: data[s][{"miner_1_20270827_breadth_defensive_trend":"trend", "miner_1_20300617_downside_sortino30_60":"down", "miner_1_20300715_path_efficiency20":"path", "miner_1_20281120_vix_gated_reversal20":"vixrev", "miner_3_20270503_vix_stress_reversal":"stressrev"}[fid]] for s in UNIVERSE}
        if fid.endswith("vix_gated_reversal20") and not vix_on: vals = {s: 0.0 for s in UNIVERSE}
        if fid.endswith("vix_stress_reversal") and not stress: vals = {s: 0.0 for s in UNIVERSE}
        rr = _rank({s: directions[fid]*vals[s] for s in UNIVERSE})
        for s in UNIVERSE: score[s] += weights[fid]*(rr[s]-.5)
    breadth = np.mean([data[s]["trend"] > 0 for s in UNIVERSE])
    if breadth < .45 or np.mean([data[s]["vol"] for s in UNIVERSE]) > .018:
        for s in DEFENSIVE: score[s] += .08
        for s in ("BTC", "ETH", "WTI"): score[s] -= .035
    inv = np.mean([1/data[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s])*(.85+.15*(1/data[s]["vol"])/inv) for s in UNIVERSE}
    target = _weights(raw)
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-avg)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

