UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def _ensemble():
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs[:10] if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def _rank(values):
    finite = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    if finite:
        for i, (s, _) in enumerate(finite): out[s] = (i + .5) / len(finite)
    return out


def _weights(raw):
    # Sensible diversification for a 15-name cross-asset universe; exact sum is enforced.
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(20):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-12: break
        free = [s for s in UNIVERSE if (.02 < w[s] < .16) or (gap > 0 and w[s] < .16) or (gap < 0 and w[s] > .02)]
        if not free: break
        for s in free: w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    ensemble = _ensemble()
    if not ensemble: return
    ids = [str(f["factor_id"]) for f in ensemble]
    fw = {str(f["factor_id"]): float(f["weight"]) for f in ensemble}
    direction = {str(f["factor_id"]): float(f.get("direction", 1)) for f in ensemble}
    data, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
