        down40 = max(np.sqrt(np.mean(np.minimum(r[-40:], 0.) ** 2)), .008)
        r20, r40 = c[-1] / c[-21] - 1., c[-1] / c[-41] - 1.
        data[s] = {"breadth": r20 / (v40 + .01) + .25 * np.mean(r[-20:] > 0),
