        except Exception: pass

    score = {s: .5 for s in UNIVERSE}
    vix = get_index_daily_data(symbol="VIX", days=80)
    vhigh = False
    if vix is not None and len(vix) >= 61:
        vc = np.asarray(vix.sort_values("date")["close"], float)[:-1]
        vhigh = bool(vc[-1] > np.median(vc[-60:]))
    for f in ensemble:
        fid = str(f["factor_id"])
        if fid == "miner_1_20270827_breadth_defensive_trend":
            vals = {s: data[s]["breadth"] for s in UNIVERSE}
        elif fid == "miner_2_20281023_downside_sharpe20":
            vals = {s: data[s]["down20"] for s in UNIVERSE}
        elif fid == "miner_3_20270827_path_efficiency40":
            vals = {s: data[s]["path40"] for s in UNIVERSE}
        elif fid == "miner_1_20281120_vix_gated_reversal20":
