        for s in DEFENSIVE: score[s] += .08
        for s in ("BTC", "ETH", "WTI"): score[s] -= .035
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    invmean = np.mean([1. / data[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15 * (1. / data[s]["vol"]) / invmean) for s in UNIVERSE}
