import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def _ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs[:10]
    except Exception:
        return []


def _rank(x):
    finite = sorted((k, v) for k, v in x.items() if np.isfinite(v))
    r = {k: .5 for k in UNIVERSE}
    for i, (k, _) in enumerate(finite):
        r[k] = (i + .5) / len(finite)
    return r


def _weights(raw):
    # Sensible 15-asset concentration limits; redistribute all residual mass.
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(30):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if (.02 + 1e-9 < w[s] < .16 - 1e-9) or (gap > 0 and w[s] < .16 - 1e-9) or (gap < 0 and w[s] > .02 + 1e-9)]
        if not free or abs(gap) < 1e-10:
            break
        for s in free:
            w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    fs = _ensemble()
    if not fs or len(fs) > 10:
        return
    ids = [str(f["factor_id"]) for f in fs]
    weights_f = {str(f["factor_id"]): float(f["weight"]) for f in fs}
    directions = {str(f["factor_id"]): float(f.get("direction", 1)) for f in fs}
    d, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 70:
            return
        df = df.sort_values("date")
        # The final row is the current/incomplete observation; never use it.
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 60 or not np.all(np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        r10, r20, r40 = c[-1] / c[-11] - 1, c[-1] / c[-21] - 1, c[-1] / c[-41] - 1
        down = max(float(np.sqrt(np.mean(np.minimum(r[-20:], 0.) ** 2))), .008)
        d[s] = {"reversal": -r20, "breadth": r20 / v40 + .25 * np.mean(r[-20:] > 0),
                "downside": r20 / down, "relative": r20 / v40,
                "quality": r40 / v40 + .2 * np.mean(r[-40:] > 0),
                "consistency": np.mean(r[-40:]) / v40, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass
    vix_gate = 1.0
    vx = get_index_daily_data(symbol="VIX", days=45)
    if vx is not None and len(vx) >= 22:
        v = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        if len(v) >= 21 and np.isfinite(v[-1]) and np.isfinite(v[-21]):
            vix_gate = min(1.8, max(.6, v[-1] / max(v[-21], 1e-9)))
    signals = {
        "miner_1_20281120_vix_gated_reversal20": {s: d[s]["reversal"] * vix_gate for s in UNIVERSE},
        "miner_1_20270827_breadth_defensive_trend": {s: d[s]["breadth"] for s in UNIVERSE},
        "miner_2_20281023_downside_sharpe20": {s: d[s]["downside"] for s in UNIVERSE},
        "miner_1_20280703_relative_trend20_vol40": {s: d[s]["relative"] for s in UNIVERSE},
        "miner_1_20270609_quality_momentum": {s: d[s]["quality"] for s in UNIVERSE},
        "miner_2_20281009_trend_consistency_volscaled": {s: d[s]["consistency"] for s in UNIVERSE}}
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in signals:
            return
        rr = _rank({s: directions[fid] * signals[fid][s] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights_f[fid] * (rr[s] - .5)
    vol = np.mean([d[s]["vol"] for s in UNIVERSE])
    breadth = np.mean([d[s]["breadth"] > 0 for s in UNIVERSE])
    if vol > .018 or breadth < .40:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv = np.mean([1 / d[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15 * (1 / d[s]["vol"]) / inv) for s in UNIVERSE}
    target = _weights(raw)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

