import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
last_decision = None


def rank_cs(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + .5) / n
    return out


def bounded(raw):
    # Bounds retain diversification in the 15-name, full-investment universe.
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(30):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if (.02 + 1e-10 < w[s] < .16 - 1e-10)]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs:
        return
    ids = [str(x["factor_id"]) for x in fs]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in fs}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in fs}
    data = {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 70:
            return
        df = df.sort_values("date")
        # The final row is the current/incomplete session; lag one session.
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 60 or not np.all(np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        r2, r10, r20, r40 = c[-1]/c[-3]-1, c[-1]/c[-11]-1, c[-1]/c[-21]-1, c[-1]/c[-41]-1
        downside = max(float(np.sqrt(np.mean(np.minimum(r[-40:], 0)**2))), .008)
        pos20, pos40 = np.mean(r[-20:] > 0), np.mean(r[-40:] > 0)
        data[s] = dict(reversal=-r20/v40, asym=-r2/v20, volume=-r2/v20,
                       defensive=.7*(r20/v40)+.3*pos40, momentum=r20/v40,
                       downside=-downside/v40 + .35*pos40, agreement=(r10+r20+r40)/(3*v40),
                       consistency=pos40*r40/v40, residual=-r20-.5*r40, vol=v20)
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_decision))/np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass

    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) >= 62:
        vv = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(vv[-1]) and vv[-1] >= np.median(vv[-60:]))
    signal = {}
    for f in fs:
        fid = str(f["factor_id"])
        if "vix_gated_reversal" in fid:
            signal[fid] = {s: data[s]["reversal"] * (0.35 if vix_high else 1.) for s in UNIVERSE}
        elif "breadth_defensive" in fid:
            signal[fid] = {s: data[s]["defensive"] for s in UNIVERSE}
        elif "risk_adjusted_20d_momentum" in fid:
            signal[fid] = {s: data[s]["momentum"] for s in UNIVERSE}
        elif "downside_sharpe40" in fid:
            signal[fid] = {s: data[s]["downside"] for s in UNIVERSE}
        elif "asymmetric_volatility_reversal" in fid:
            signal[fid] = {s: data[s]["asym"] for s in UNIVERSE}
        elif "residual_reversal20" in fid:
            signal[fid] = {s: data[s]["residual"] for s in UNIVERSE}
        elif "multihorizon_agreement" in fid:
            signal[fid] = {s: data[s]["agreement"] for s in UNIVERSE}
        elif "trend_consistency_volscaled" in fid:
            signal[fid] = {s: data[s]["consistency"] for s in UNIVERSE}
        elif "volume_confirmed_reversal" in fid:
            signal[fid] = {s: data[s]["volume"] for s in UNIVERSE}
        else:
            return

    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        rr = rank_cs({s: directions[fid] * signal[fid][s] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (rr[s] - .5)
    breadth = np.mean([data[s]["momentum"] > 0 for s in UNIVERSE])
    stress = vix_high or breadth < .40 or np.mean([data[s]["vol"] for s in UNIVERSE]) > .018
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv = np.mean([1/data[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15*(1/data[s]["vol"])/inv) for s in UNIVERSE}
    w = bounded(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(w, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

