from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def ranks(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + .5) / len(good)
    return out


def project(raw):
    # 15-asset, long-only, fully invested allocation; fractional quantities are handled by helper.
    w = {s: min(.16, max(.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(60):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if .020001 < w[s] < .159999]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(.16, max(.02, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs:
        return
    ids = [str(f["factor_id"]) for f in fs]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in fs}
    directions = {str(f["factor_id"]): float(f.get("direction", 1)) for f in fs}
    d, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 70:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]  # completed sessions only
        if len(c) < 60 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
        r2, r3, r10, r20, r40 = c[-1]/c[-3]-1, c[-1]/c[-4]-1, c[-1]/c[-11]-1, c[-1]/c[-21]-1, c[-1]/c[-41]-1
        down = max(np.sqrt(np.mean(np.minimum(r[-40:], 0)**2)), .008)
        up = max(np.sqrt(np.mean(np.maximum(r[-40:], 0)**2)), .008)
        pos20, pos40 = np.mean(r[-20:] > 0), np.mean(r[-40:] > 0)
        vol = np.asarray(df["volume"], dtype=float)[:-1] if "volume" in df else np.ones(len(c))
        vr = (vol[-3:].mean() / max(vol[-20:].mean(), 1e-12)) if len(vol) >= 20 else 1.
        d[s] = {"rev": -r20/v40, "def": .7*r20/v40 + .3*pos40,
                "trend": r20/v40, "down": -down/v40 + .35*pos40,
                "agree": (r10+r20+r40)/(3*v40), "cons": pos40*r40/v40,
                "resid": -r20-.5*r40, "quality": .5*pos40 + .5*r20/v40,
                "asym": -r2 * (up / down), "volume_rev": -r3 * min(vr, 2.0),
                "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass
    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) >= 62:
        vv = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(vv[-1]) and vv[-1] >= np.median(vv[-60:]))
    breadth = np.mean([d[s]["trend"] > 0 for s in UNIVERSE])
    signal = {}
    for f in fs:
        fid = str(f["factor_id"])
        if "vix_gated_reversal" in fid: x, gate = "rev", (.35 if vix_high else 1.)
        elif "breadth_defensive" in fid: x, gate = "def", 1.
        elif "trend_consistency_volscaled" in fid: x, gate = "cons", 1.
        elif "breadth_gated_relative_trend" in fid: x, gate = "trend", (.7 if breadth < .5 else 1.)
        elif "relative_trend20_vol40" in fid: x, gate = "trend", 1.
        elif "downside_sharpe" in fid: x, gate = "down", 1.
        elif "risk_adjusted_20d_momentum" in fid: x, gate = "trend", 1.
        elif "asymmetric_volatility_reversal" in fid: x, gate = "asym", 1.
        elif "residual_reversal20" in fid: x, gate = "resid", 1.
        elif "multihorizon_agreement" in fid: x, gate = "agree", 1.
        elif "volume_confirmed_reversal" in fid: x, gate = "volume_rev", 1.
        elif "quality_momentum" in fid: x, gate = "quality", 1.
        else: return
        signal[fid] = {s: gate * d[s][x] for s in UNIVERSE}
    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        rr = ranks({s: directions[fid] * signal[fid][s] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (rr[s] - .5)
    stress = vix_high or breadth < .40 or np.mean([d[s]["vol"] for s in UNIVERSE]) > .018
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    avg_inv = np.mean([1/d[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15*(1/d[s]["vol"])/avg_inv) for s in UNIVERSE}
    target = project(raw)
    mean, std = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp
