import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def cs_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 0.5) / len(valid)
    return out


def full_investment(raw):
    # Sensible diversification for a 15-name universe; no cash sleeve.
    lo, hi = 0.02, 0.16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-11:
            break
        free = [s for s in UNIVERSE if lo + 1e-9 < w[s] < hi - 1e-9]
        if not free:
            break
        add = gap / len(free)
        for s in free:
            w[s] = min(hi, max(lo, w[s] + add))
    # The feasible box contains sum=1; normalize only for floating point residue.
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    ids = [str(f["factor_id"]) for f in selected]
    factor_weight = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    direction = {str(f["factor_id"]): float(f.get("direction", 1)) for f in selected}

    feat, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 70:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)[:-1]  # only completed sessions
        if len(close) < 60 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20 = max(float(np.std(ret[-20:])), 0.008)
        v40 = max(float(np.std(ret[-40:])), 0.008)
        r2 = close[-1] / close[-3] - 1
        r10 = close[-1] / close[-11] - 1
        r20 = close[-1] / close[-21] - 1
        r40 = close[-1] / close[-41] - 1
        down = max(float(np.sqrt(np.mean(np.minimum(ret[-40:], 0) ** 2))), 0.008)
        pos40 = float(np.mean(ret[-40:] > 0))
        feat[symbol] = {
            "rev": -r20 / v40,
            "def": 0.7 * r20 / v40 + 0.3 * pos40,
            "down": -down / v40 + 0.35 * pos40,
            "cons": pos40 * r40 / v40,
            "trend": r20 / v40,
            "quality": 0.5 * pos40 + 0.5 * r20 / v40,
            "vol": v20,
        }
        stamp = str(df.iloc[-2]["date"])

    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass

    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) >= 62:
        v = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(v[-1]) and v[-1] >= np.median(v[-60:]))
    breadth = float(np.mean([feat[s]["trend"] > 0 for s in UNIVERSE]))
    signal = {}
    for f in selected:
        fid = str(f["factor_id"])
        if "vix_gated_reversal" in fid:
            key, gate = "rev", (0.35 if vix_high else 1.0)
        elif "breadth_defensive_trend" in fid:
            key, gate = "def", 1.0
        elif "downside_sharpe" in fid:
            key, gate = "down", 1.0
        elif "trend_consistency_volscaled" in fid:
            key, gate = "cons", 1.0
        elif "breadth_gated_relative_trend" in fid:
            key, gate = "trend", (0.7 if breadth < 0.5 else 1.0)
        elif "quality_momentum" in fid:
            key, gate = "quality", 1.0
        else:
            return
        signal[fid] = {s: gate * feat[s][key] for s in UNIVERSE}

    score = {s: 0.5 for s in UNIVERSE}
    for fid in ids:
        ranked = cs_rank({s: direction[fid] * signal[fid][s] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += factor_weight[fid] * (ranked[s] - 0.5)
    stress = vix_high or breadth < 0.40 or np.mean([feat[s]["vol"] for s in UNIVERSE]) > 0.018
    if stress:
        for s in DEFENSIVE:
            score[s] += 0.06
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.03
    inv_mean = float(np.mean([1.0 / feat[s]["vol"] for s in UNIVERSE]))
    raw = {s: max(0.04, score[s]) * (0.85 + 0.15 * (1.0 / feat[s]["vol"]) / inv_mean) for s in UNIVERSE}
    target = full_investment(raw)
    mean = float(np.mean(list(score.values())))
    std = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

