import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def rank_cs(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def bounded_weights(raw):
    lo, hi = 0.02, 0.16
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(50):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if lo + 1e-9 < w[s] < hi - 1e-9]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    ids = [str(f["factor_id"]) for f in selected]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    directions = {str(f["factor_id"]): float(f.get("direction", 1)) for f in selected}
    feat, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 70:
            return
        c = np.asarray(df.sort_values("date")["close"], dtype=float)[:-1]
        if len(c) < 60 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
        r20, r40 = c[-1] / c[-21] - 1, c[-1] / c[-41] - 1
        pos = np.mean(r[-40:] > 0)
        down = max(np.sqrt(np.mean(np.minimum(r[-40:], 0) ** 2)), .008)
        feat[s] = {"trend": r20 / v40, "def": .7*r20/v40 + .3*pos,
                   "down": -.5*down/v40 + .5*pos, "cons": pos*r40/v40,
                   "mom": r20/v40, "quality": .5*pos + .5*r20/v40,
                   "rev": -r20/v40, "vol": v20}
        stamp = str(df.sort_values("date").iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_decision))/np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass
    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) > 62:
        v = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(v[-1]) and v[-1] >= np.median(v[-60:]))
    breadth = np.mean([feat[s]["trend"] > 0 for s in UNIVERSE])
    signals = {}
    for f in selected:
        fid = str(f["factor_id"])
        if "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "breadth_gated_relative_trend" in fid: key, gate = "trend", (.7 if breadth < .5 else 1.0)
        elif "downside_sharpe" in fid: key, gate = "down", 1.0
        elif "trend_consistency_volscaled" in fid: key, gate = "cons", 1.0
        elif "risk_adjusted_20d_momentum" in fid: key, gate = "mom", 1.0
        elif "quality_momentum" in fid: key, gate = "quality", 1.0
        elif "vix_gated_reversal" in fid: key, gate = "rev", (.35 if not vix_high else 1.0)
        else: return
        signals[fid] = {s: gate * feat[s][key] for s in UNIVERSE}
    score = {s: .5 for s in UNIVERSE}
    for fid in ids:
        q = rank_cs({s: directions[fid] * signals[fid][s] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (q[s] - .5)
    stress = vix_high or breadth < .4 or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv = np.mean([1.0/feat[s]["vol"] for s in UNIVERSE])
    raw = {s: max(.04, score[s]) * (.85 + .15*(1.0/feat[s]["vol"])/inv) for s in UNIVERSE}
    target = bounded_weights(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

