import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def cs_rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n
    return out


def cap_weights(raw, lo=0.02, hi=0.16):
    w = {s: min(hi, max(lo, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        free = [s for s in UNIVERSE if lo < w[s] < hi]
        gap = 1.0 - sum(w.values())
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or len(selected) > 10:
        return
    ids = [str(f["factor_id"]) for f in selected]
    fweights = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    dirs = {str(f["factor_id"]): float(f.get("direction", 1)) for f in selected}
    feat = {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 80:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]  # completed sessions only
        if len(c) < 70 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
        r5, r20 = c[-1] / c[-6] - 1.0, c[-1] / c[-21] - 1.0
        breadth = np.mean(r[-40:] > 0)
        downside = max(np.sqrt(np.mean(np.minimum(r[-40:], 0.0) ** 2)), .008)
        feat[s] = {"rev": -r20 / v40, "trend": r20 / v40,
                   "def": .7 * r20 / v40 + .3 * breadth,
                   "down": -.5 * downside / v40 + .5 * breadth,
                   "mom": r20 / v40, "quality": .5 * breadth + .5 * r20 / v40,
                   "stressrev": -r5 / v20, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass
    vix = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vix is not None and len(vix) > 62:
        q = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(q[-1]) and q[-1] >= np.median(q[-60:]))
    market_breadth = np.mean([feat[s]["trend"] > 0 for s in UNIVERSE])
    score = {s: 0.5 for s in UNIVERSE}
