        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if lo < w[s] < hi]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or len(selected) > 10:
        return
    factor_ids = [str(f["factor_id"]) for f in selected]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    directions = {str(f["factor_id"]): float(f.get("direction", 1)) for f in selected}

    feat, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 90:
            return
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)[:-1]  # completed sessions only
        if len(close) < 70 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        r20 = close[-1] / close[-21] - 1.0
        r10 = close[-1] / close[-11] - 1.0
        r5 = close[-1] / close[-6] - 1.0
        v20, v40 = max(float(np.std(ret[-20:])), .008), max(float(np.std(ret[-40:])), .008)
        rr = ret[-40:]
        breadth = float(np.mean(rr > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(rr, 0.0) ** 2))), .008)
        feat[symbol] = {
            "rev": -r20 / v40, "trend": r20 / v40,
            "def": .7 * r20 / v40 + .3 * breadth,
            "down": -.5 * downside / v40 + .5 * breadth,
            "quality": .5 * breadth + .5 * r20 / v40,
            "cons": float(np.mean(rr)) / v40, "residual": -r10 / v20,
            "riskmom": r20 / v40, "persistent": -r5 / v20, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            pass

    vix = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vix is not None and len(vix) > 62:
        vc = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    breadth = float(np.mean([feat[s]["trend"] > 0 for s in UNIVERSE]))
    score = {s: .5 for s in UNIVERSE}
    for factor in selected:
        fid = str(factor["factor_id"])
        if "vix_gated_reversal" in fid: key, gate = "rev", (1.0 if vix_high else .5)
        elif "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "breadth_gated_relative_trend" in fid: key, gate = "trend", (.7 if breadth < .5 else 1.0)
        elif "downside_sharpe" in fid or "downside_sortino" in fid: key, gate = "down", 1.0
        elif "persistent_trend_reversal" in fid: key, gate = "persistent", (.8 if vix_high else .6)
        elif "quality_momentum" in fid: key, gate = "quality", 1.0
        elif "risk_adjusted_20d_momentum" in fid: key, gate = "riskmom", (.7 if breadth < .5 else 1.0)
        elif "trend_consistency" in fid: key, gate = "cons", 1.0
        elif "residual_reversal" in fid: key, gate = "residual", 1.0
        else: return
        ranks = rank({s: directions[fid] * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weights[fid] * (ranks[s] - .5)

    stress = vix_high or breadth < .4 or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    invmean = float(np.mean([1.0 / feat[s]["vol"] for s in UNIVERSE]))
    raw = {s: max(.04, score[s]) * (.85 + .15 * (1.0 / feat[s]["vol"]) / invmean) for s in UNIVERSE}
    target = bounded(raw)
    mean, std = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_decision = stamp

