import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def cross_rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n
    return out


def bounded_weights(score):
    # Diversified long-only allocation, with a modest 2% floor and 16% cap.
    a = np.asarray([score[s] for s in UNIVERSE], dtype=float)
    a = np.exp(np.clip(2.0 * (a - np.mean(a)), -3.0, 3.0))
    a = a / a.sum()
    w = {s: 0.02 + 0.78 * float(a[i]) for i, s in enumerate(UNIVERSE)}
    # The construction sums to one; cap excess and redistribute to uncapped names.
    for _ in range(20):
        excess = sum(max(0.0, x - 0.16) for x in w.values())
        for s in UNIVERSE:
            w[s] = min(w[s], 0.16)
        free = [s for s in UNIVERSE if w[s] < 0.16 - 1e-12]
        if excess <= 1e-10 or not free:
            break
        add = excess / len(free)
        for s in free:
            w[s] = min(0.16, w[s] + add)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
    except Exception:
        return
    selected = selected[:10]
    if not selected:
        return
    ids = [str(x["factor_id"]) for x in selected]
    fw = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in selected}
    if len(ids) > 10 or abs(sum(fw.values()) - 1.0) > 1e-5:
        return

    feat, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]
        if len(c) < 70 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.008)
        v40 = max(float(np.std(r[-40:])), 0.008)
        r5, r20 = c[-1] / c[-6] - 1.0, c[-1] / c[-21] - 1.0
        rr = r[-40:]
        breadth = float(np.mean(rr > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(rr, 0.0) ** 2))), 0.008)
        trend = r20 / v40
        feat[s] = {"trend": trend, "def": .7 * trend + .3 * breadth,
                   "down": .5 * breadth - .5 * downside / v40,
                   "rev": -trend, "persistent": -r5 / v20,
                   "quality": .5 * breadth + .5 * trend, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return

    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) > 62:
        vc = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    market_breadth = np.mean([feat[s]["trend"] > 0 for s in UNIVERSE])
    stress = vix_high or market_breadth < .4 or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    score = {s: 0.5 for s in UNIVERSE}
    for item in selected:
        fid = str(item["factor_id"])
        if "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "downside_sharpe" in fid: key, gate = "down", 1.0
        elif "vix_gated_reversal" in fid: key, gate = "rev", .35 if vix_high else 1.0
        elif "persistent_trend_reversal" in fid: key, gate = "persistent", .8 if vix_high else .6
        elif "quality_momentum" in fid or "trend_consistency_volscaled" in fid: key, gate = "quality", 1.0
        elif "multihorizon_agreement" in fid: key, gate = "trend", 1.0
        else: return
        ranks = cross_rank({s: directions[fid] * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += fw[fid] * (ranks[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    mean_inv = np.mean([1.0 / feat[s]["vol"] for s in UNIVERSE])
    score = {s: score[s] * (.85 + .15 * (1.0 / feat[s]["vol"]) / mean_inv) for s in UNIVERSE}
    target = bounded_weights(score)
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - avg) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

strategy = cross_asset_strategy

