import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def cross_rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    if n:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 0.5) / n
    return out


def bounded_weights(score):
    # Full investment, diversified across the deliberately small 15-name universe.
    a = np.asarray([score[s] for s in UNIVERSE], dtype=float)
    a = np.exp(np.clip(2.0 * (a - np.mean(a)), -3.0, 3.0))
    a /= a.sum()
    w = {s: 0.02 + 0.78 * float(a[i]) for i, s in enumerate(UNIVERSE)}
    for _ in range(20):
        excess = sum(max(0.0, x - 0.16) for x in w.values())
        for s in UNIVERSE:
            w[s] = min(w[s], 0.16)
        free = [s for s in UNIVERSE if w[s] < 0.16 - 1e-12]
        if excess <= 1e-10 or not free:
            break
        for s in free:
            w[s] = min(0.16, w[s] + excess / len(free))
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    ids = [str(x["factor_id"]) for x in selected]
    fw = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in selected}
    if len(ids) > 10 or abs(sum(fw.values()) - 1.0) > 1e-5:
        return

    feat, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)[:-1]  # never use today's incomplete bar
        if len(c) < 70 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20, v40 = max(float(np.std(r[-20:])), .008), max(float(np.std(r[-40:])), .008)
        r5, r20 = c[-1] / c[-6] - 1, c[-1] / c[-21] - 1
        rr = r[-40:]
        breadth = float(np.mean(rr > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(rr, 0) ** 2))), .008)
