    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return

    vx = get_index_daily_data(symbol="VIX", days=80)
    vix_high = False
    if vx is not None and len(vx) > 62:
        vc = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        vix_high = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    breadth_market = np.mean([feat[s]["trend"] > 0 for s in UNIVERSE])
    stress = vix_high or breadth_market < .4 or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    score = {s: .5 for s in UNIVERSE}
    for item in selected:
        fid = str(item["factor_id"])
        if "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "downside_sharpe" in fid: key, gate = "down", 1.0
        elif "vix_gated_reversal" in fid: key, gate = "rev", .35 if vix_high else 1.0
        elif "persistent_trend_reversal" in fid: key, gate = "persistent", .8 if vix_high else .6
        elif "quality_momentum" in fid or "trend_consistency_volscaled" in fid: key, gate = "quality", 1.0
        elif "multihorizon_agreement" in fid: key, gate = "trend", 1.0
        elif "path_efficiency20" in fid: key, gate = "path", 1.0
        else: return
        ranks = cross_rank({s: directions[fid] * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += fw[fid] * (ranks[s] - .5)
