        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    mean_inv = np.mean([1 / feat[s]["vol"] for s in UNIVERSE])
    score = {s: score[s] * (.85 + .15 * (1 / feat[s]["vol"]) / mean_inv) for s in UNIVERSE}
    target = bounded_weights(score)
