import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
last_decision = None


def pct_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / n
    return out


def make_weights(score):
    x = np.asarray([score[s] for s in UNIVERSE], float)
    z = np.exp(np.clip(2.0 * (x - x.mean()), -3, 3)); z /= z.sum()
    # Full investment, diversified 2%-16% bounds; no cash sleeve.
    w = {s: 0.02 + 0.78 * z[i] for i, s in enumerate(UNIVERSE)}
    for _ in range(30):
        excess = sum(max(0.0, v - 0.16) for v in w.values())
        for s in UNIVERSE: w[s] = min(0.16, w[s])
        free = [s for s in UNIVERSE if w[s] < 0.16 - 1e-10]
        if excess < 1e-10 or not free: break
        for s in free: w[s] = min(0.16, w[s] + excess / len(free))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8"))["selected_factors"][:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-5:
        return
    ids = [str(x["factor_id"]) for x in selected]
    weights_by_factor = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in selected}

    feat = {}
    stamp = None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=260)
        if df is None or len(df) < 100: return
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)[:-1]  # only completed bars
        if len(c) < 70 or np.any(~np.isfinite(c)) or np.any(c <= 0): return
        r = c[1:] / c[:-1] - 1
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        r5, r20, r40 = c[-1]/c[-6]-1, c[-1]/c[-21]-1, c[-1]/c[-41]-1
        recent = r[-40:]
        breadth = float(np.mean(recent > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(recent, 0)**2))), .008)
        trend = r20 / v40
        path = abs(r40) / max(float(np.sum(np.abs(r[-40:]))), .01)
        consistency = float(np.mean(np.sign(r[-20:]) == np.sign(np.mean(r[-20:])))) / v20
        feat[s] = {"def": .7*trend + .3*breadth, "down": .5*breadth - .5*downside/v40,
                   "relative": trend, "rev": -trend, "persistent": -r5/v20,
                   "path": path, "consistency": consistency, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp)-np.datetime64(last_decision))/np.timedelta64(1, "D") < 14: return
        except Exception: return

    vx = get_index_daily_data(symbol="VIX", days=80)
    high_vix = False
    if vx is not None and len(vx) > 62:
        vc = np.asarray(vx.sort_values("date")["close"], float)[:-1]
        high_vix = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    stress = high_vix or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    score = {s: .5 for s in UNIVERSE}
    for item in selected:
        fid = str(item["factor_id"])
        if "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "downside_sharpe20" in fid: key, gate = "down", 1.0
        elif "breadth_gated_relative_trend" in fid: key, gate = "relative", 1.0
        elif "vix_gated_reversal20" in fid: key, gate = "rev", .35 if high_vix else 1.0
        elif "persistent_trend_reversal" in fid: key, gate = "persistent", .6 if high_vix else .8
        elif "path_efficiency40" in fid: key, gate = "path", 1.0
        elif "trend_consistency_volscaled" in fid: key, gate = "consistency", 1.0
        elif "vix_stress_reversal" in fid: key, gate = "rev", .25 if high_vix else .1
        else: return
        ranks = pct_rank({s: directions[fid] * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE: score[s] += weights_by_factor[fid] * (ranks[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    avg_inv = np.mean([1.0/feat[s]["vol"] for s in UNIVERSE])
    score = {s: score[s] * (.85 + .15*(1.0/feat[s]["vol"])/avg_inv) for s in UNIVERSE}
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01*(score[s]-avg)/sd) for s in UNIVERSE}
    rebalance_to_weights(make_weights(score), forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = stamp

strategy = cross_asset_strategy

