import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def rank_cs(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return out
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 0.5) / len(valid)
    return out


def bounded_weights(score):
    # Capped simplex projection: every tradable asset remains invested.
    x = np.exp(np.clip(2.0 * (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))), -3, 3))
    x /= x.sum()
    lo, hi = 0.02, 0.16
    w = np.full(len(UNIVERSE), lo)
    remaining = 1.0 - lo * len(UNIVERSE)
    active = np.ones(len(UNIVERSE), dtype=bool)
    while active.any() and remaining > 0:
        p = x * active
        p /= p.sum()
        add = np.minimum(hi - lo, remaining * p)
        w += add
        remaining -= float(add.sum())
        active &= (w < hi - 1e-10) & (add > 1e-12)
        if add.sum() < 1e-12:
            break
    if remaining > 1e-10:
        eligible = w < hi - 1e-10
        w[eligible] += remaining / eligible.sum()
    w /= w.sum()
    return {s: float(v) for s, v in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-5:
        return
