        if len(c) < 70 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            return
        r = c[1:] / c[:-1] - 1.0
        v20, v40 = max(float(np.std(r[-20:])), .008), max(float(np.std(r[-40:])), .008)
        r5, r20 = c[-1] / c[-6] - 1.0, c[-1] / c[-21] - 1.0
        rr = r[-40:]
        breadth = float(np.mean(rr > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(rr, 0.0) ** 2))), .008)
        trend = r20 / v40
        feat[s] = {"def": .7 * trend + .3 * breadth, "down": .5 * breadth - .5 * downside / v40,
                   "relative": trend, "rev": -trend, "persistent": -r5 / v20, "vol": v20}
        stamp = str(df.iloc[-2]["date"])
    if last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return

    vix = get_index_daily_data(symbol="VIX", days=80)
    high_vix = False
    if vix is not None and len(vix) > 62:
        vc = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        high_vix = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    stress = high_vix or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018
    score = {s: .5 for s in UNIVERSE}
    for f in selected:
        fid = str(f["factor_id"])
        if "breadth_defensive_trend" in fid: key, gate = "def", 1.0
        elif "vix_gated_reversal20" in fid: key, gate = "rev", .35 if high_vix else 1.0
        elif "persistent_trend_reversal" in fid: key, gate = "persistent", .6 if high_vix else .8
        elif "quality_momentum" in fid: key, gate = "def", .75
        elif "downside_sharpe20" in fid: key, gate = "down", 1.0
        elif "breadth_gated_relative_trend" in fid: key, gate = "relative", 1.0
        elif "vix_stress_reversal" in fid: key, gate = "rev", .25 if high_vix else .1
        else: return
        ranks = rank_cs({s: direction[fid] * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += fw[fid] * (ranks[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv = {s: 1.0 / feat[s]["vol"] for s in UNIVERSE}
