DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def cs_rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + .5) / len(valid)
    return out


def weights(score):
    # Full investment, deliberately moderate concentration for this 15-asset universe.
    x = np.exp(np.clip(2.0 * (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))), -3, 3))
    x /= x.sum()
    lo, hi = .02, .16
    w = np.full(15, lo); remaining = 1.0 - 15 * lo
    active = np.ones(15, dtype=bool)
    while remaining > 1e-12 and active.any():
        p = x * active; p /= p.sum()
        add = np.minimum(hi - lo, remaining * p)
        w += add; remaining -= float(add.sum())
        active &= (w < hi - 1e-10) & (add > 1e-12)
        if float(add.sum()) < 1e-12: break
    if remaining > 1e-10:
        ok = w < hi - 1e-10
        w[ok] += remaining / ok.sum()
    w /= w.sum()
    return {s: float(v) for s, v in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
