import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
# Screener output is persisted at the workspace root.
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_last_stamp = None


def cs_rank(values):
    finite = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not finite:
        return out
    for i, (s, _) in enumerate(finite):
        out[s] = (i + 0.5) / len(finite)
    return out


def bounded_weights(score):
    # Full investment across all 15 assets; 2% floor, 16% ceiling.
    w = np.full(len(UNIVERSE), 0.02)
    room = 1.0 - w.sum()
    z = np.exp(np.clip(2.0 * (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))), -4, 4))
    active = np.ones(len(UNIVERSE), dtype=bool)
    while room > 1e-10 and active.any():
        p = z * active
        p /= p.sum()
        add = np.minimum(0.16 - w, room * p)
        w += add
        used = float(add.sum())
        room -= used
        active &= (0.16 - w > 1e-10)
        if used < 1e-12:
            break
    if room > 1e-9 and active.any():
        w[active] += room / active.sum()
    w /= w.sum()
    return dict(zip(UNIVERSE, [float(x) for x in w]))


@register_hook
def cross_asset_strategy():
    global _last_stamp
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f.get("weight", 0)) for f in selected) - 1.0) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in selected]
    factors = {str(f["factor_id"]): (float(f["weight"]), float(f.get("direction", 1))) for f in selected}

    feat, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=280)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        # Exclude the unfinished/current bar: decisions use completed history only.
        close = np.asarray(df["close"], dtype=float)[:-1]
        if len(close) < 70 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        ret = close[1:] / close[:-1] - 1.0
        v20, v40 = max(float(np.std(ret[-20:])), .008), max(float(np.std(ret[-40:])), .008)
        trend = (close[-1] / close[-21] - 1.0) / v40
        breadth = float(np.mean(ret[-40:] > 0))
        downside = max(float(np.sqrt(np.mean(np.minimum(ret[-20:], 0.0) ** 2))), .008)
        feat[symbol] = {
            "defensive": .7 * trend + .3 * breadth,
            "downside": .5 * breadth - .5 * downside / v40,
            "reversal": -trend,
            "persistent_reversal": -(close[-1] / close[-6] - 1.0) / v20,
            "quality": .7 * trend + .3 * breadth,
            "momentum": trend,
            "relative_trend": trend / max(v40, .008),
            "vol": v20,
        }
        stamp = str(df.iloc[-2]["date"])

    if _last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(_last_stamp)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return

    vix = get_index_daily_data(symbol="VIX", days=80)
    high_vix = False
    if vix is not None and len(vix) > 62:
        vc = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        high_vix = bool(np.isfinite(vc[-1]) and vc[-1] >= np.median(vc[-60:]))
    stress = high_vix or np.mean([feat[s]["vol"] for s in UNIVERSE]) > .018

    score = {s: .5 for s in UNIVERSE}
    for fid, (weight, direction) in factors.items():
        gate = 1.0
        if "breadth_defensive_trend" in fid:
            key = "defensive"
        elif "vix_gated_reversal20" in fid:
            key, gate = "reversal", (1.0 if high_vix else .2)
        elif "downside_sharpe20" in fid:
            key = "downside"
        elif "breadth_gated_relative_trend" in fid:
            key = "relative_trend"
        elif "persistent_trend_reversal" in fid:
            key, gate = "persistent_reversal", (.6 if high_vix else .8)
        elif "quality_momentum" in fid:
            key = "quality"
        elif "risk_adjusted_20d_momentum" in fid:
            key = "momentum"
        else:
            return
        ranks = cs_rank({s: direction * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += weight * (ranks[s] - .5)

    if stress:
        for s in DEFENSIVE:
            score[s] += .06
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .03
    inv = {s: 1.0 / feat[s]["vol"] for s in UNIVERSE}
    avg_inv = np.mean(list(inv.values()))
    score = {s: score[s] * (.85 + .15 * inv[s] / avg_inv) for s in UNIVERSE}
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(bounded_weights(score), forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _last_stamp = stamp


strategy = cross_asset_strategy

