    while room > 1e-10 and active.any():
        p = z * active
        p /= p.sum()
        add = np.minimum(0.16 - w, room * p)
        w += add
        used = float(add.sum())
        room -= used
        active &= (0.16 - w > 1e-10)
        if used < 1e-12:
