DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_last_stamp = None


def cross_rank(values):
    finite = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if finite:
        for i, (s, _) in enumerate(finite):
            out[s] = (i + 0.5) / len(finite)
    return out


def bounded_weights(score):
    # Full investment, diversified 2%-16% bounds; no cash sleeve.
    w = np.full(len(UNIVERSE), 0.02)
    room = 1.0 - float(w.sum())
    z = np.exp(np.clip(2.0 * (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))), -4, 4))
    active = np.ones(len(UNIVERSE), dtype=bool)
    while room > 1e-10 and active.any():
        p = z * active
        p /= p.sum()
        add = np.minimum(0.16 - w, room * p)
        w += add
        room -= float(add.sum())
        active &= w < 0.16 - 1e-10
        if float(add.sum()) < 1e-12:
            break
    if room > 1e-9 and active.any():
        w[active] += room / active.sum()
    w /= w.sum()
    return dict(zip(UNIVERSE, [float(x) for x in w]))


