DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def rank(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def weights(scores):
    # Full investment, sensible diversification for a 15-name universe.
    w = np.full(15, 0.02)
    room = 1.0 - w.sum()
    z = np.exp(np.clip(2.2 * (np.array([scores[s] for s in UNIVERSE]) - np.mean(list(scores.values()))), -4, 4))
    while room > 1e-10:
        eligible = w < 0.16 - 1e-10
        if not eligible.any():
            break
        p = z * eligible
        p /= p.sum()
        add = np.minimum(0.16 - w, room * p)
        w += add
        used = float(add.sum())
        room -= used
        if used < 1e-12:
            break
    if room > 1e-10:
        w += room / 15.0
    w /= w.sum()
    return dict(zip(UNIVERSE, map(float, w)))


@register_hook
def cross_asset_strategy():
    global last_stamp
    try:
        selected = json.loads(ENSEMBLE.read_text(encoding="utf-8"))["selected_factors"][:10]
