        elif "dispweighted_residual_reversal15" in fid: key, gate = "resid15", (.5 if stress else .75)
        elif "residual_volscaled_reversal20" in fid: key, gate = "rev20", (.65 if stress else 1)
        else: return
        rr = rank({s: direction * gate * feat[s][key] for s in UNIVERSE})
        for s in UNIVERSE: score[s] += wt * (rr[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    inv = {s: 1 / feat[s]["vol"] for s in UNIVERSE}
    mean_inv = np.mean(list(inv.values()))
    score = {s: score[s] * (.85 + .15 * inv[s] / mean_inv) for s in UNIVERSE}
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s]-mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights(score), forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
