import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE_FILE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_last_decision = None


def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    result = {s: 0.5 for s in UNIVERSE}
    for i, (symbol, _) in enumerate(valid):
        result[symbol] = (i + 0.5) / len(valid)
    return result


def bounded_weights(scores):
    # Complete long-only portfolio: 2% floor, 16% ceiling, no cash sleeve.
    weights = np.full(len(UNIVERSE), 0.02, dtype=float)
    room = 1.0 - weights.sum()
    centered = np.array([scores[s] for s in UNIVERSE]) - np.mean(list(scores.values()))
    preference = np.exp(np.clip(2.2 * centered, -4.0, 4.0))
    while room > 1e-10:
        eligible = weights < 0.16 - 1e-10
        if not eligible.any():
            break
        p = preference * eligible
        p /= p.sum()
        add = np.minimum(0.16 - weights, room * p)
        weights += add
        used = float(add.sum())
        room -= used
        if used < 1e-12:
            break
    if room > 1e-10:
        weights += room / len(UNIVERSE)
    weights /= weights.sum()
    return dict(zip(UNIVERSE, weights.tolist()))


@register_hook
def cross_asset_strategy():
    global _last_decision
    try:
        factors = json.loads(ENSEMBLE_FILE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]
    features, stamp = {}, None
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=280)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        # Exclude the latest potentially incomplete session.
        close = np.asarray(df["close"], dtype=float)[:-1]
        if len(close) < 70 or np.any(~np.isfinite(close)) or np.any(close <= 0):
            return
        returns = close[1:] / close[:-1] - 1.0
        vol20 = max(float(np.std(returns[-20:])), 0.008)
        vol40 = max(float(np.std(returns[-40:])), 0.008)
        trend20 = (close[-1] / close[-21] - 1.0) / vol40
        trend40 = (close[-1] / close[-41] - 1.0) / vol40
        downside = max(float(np.sqrt(np.mean(np.minimum(returns[-20:], 0.0) ** 2))), 0.008)
        features[symbol] = {
            "trend": 0.7 * trend20 + 0.3 * float(np.mean(returns[-40:] > 0)),
            "down": 0.5 * float(np.mean(returns[-40:] > 0)) - 0.5 * downside / vol40,
            "cons": 0.6 * trend20 + 0.4 * trend40,
            "rev20": -trend20,
            "resid15": close[-1] / close[-6] - 1.0,
            "vol": vol20,
        }
        stamp = str(df.iloc[-2]["date"])
    if _last_decision is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(_last_decision)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return

    median_residual = float(np.median([features[s]["resid15"] for s in UNIVERSE]))
    for symbol in UNIVERSE:
        f = features[symbol]
        f["resid15"] = -(f["resid15"] - median_residual) / f["vol"]

    vix = get_index_daily_data(symbol="VIX", days=80)
    high_vix = False
    if vix is not None and len(vix) > 62:
        values = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        high_vix = bool(len(values) and np.isfinite(values[-1]) and values[-1] >= np.median(values[-60:]))
    stress = high_vix or np.mean([features[s]["vol"] for s in UNIVERSE]) > 0.018

    scores = {s: 0.5 for s in UNIVERSE}
    for factor in factors:
        fid = str(factor["factor_id"])
        weight = float(factor["weight"])
        direction = float(factor.get("direction", 1))
        if "breadth_defensive_trend" in fid:
            key, gate = "trend", 1.0
        elif "trend_consistency_volscaled" in fid:
            key, gate = "cons", 1.0
        elif "downside_sharpe20" in fid:
            key, gate = "down", 1.0
        elif "vix_gated_reversal20" in fid:
            key, gate = "rev20", 1.0 if high_vix else 0.25
        elif "robust_dispweighted_residual_reversal15" in fid:
            key, gate = "resid15", 0.5 if stress else 0.75
        elif "downsidepath_reversal20" in fid:
            # Path-adjusted reversal proxy; gated because coverage is partial.
            key, gate = "rev20", 0.55 if stress else 0.8
        else:
            return
        ranks = cross_rank({s: direction * gate * features[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            scores[s] += weight * (ranks[s] - 0.5)

    if stress:
        for s in DEFENSIVE:
            scores[s] += 0.06
        for s in ("BTC", "ETH", "WTI"):
            scores[s] -= 0.03
    inv_vol = {s: 1.0 / features[s]["vol"] for s in UNIVERSE}
    avg_inv = np.mean(list(inv_vol.values()))
    scores = {s: scores[s] * (0.85 + 0.15 * inv_vol[s] / avg_inv) for s in UNIVERSE}
    mean, std = np.mean(list(scores.values())), max(float(np.std(list(scores.values()))), 1e-8)
    forecast_returns = {s: float(0.01 * (scores[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(bounded_weights(scores), forecast_returns=forecast_returns,
                         factor_ids=factor_ids, horizon_days=10)
    _last_decision = stamp


strategy = cross_asset_strategy

