                return
        except Exception:
            return
    vix = get_index_daily_data(symbol="VIX", days=80)
    high_vix = False
    if vix is not None and len(vix) > 62:
        x = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        high_vix = bool(np.isfinite(x[-1]) and x[-1] >= np.median(x[-60:]))
    stress = high_vix or np.mean([d["vol"] for d in data.values()]) > .018
    score = {s: .5 for s in UNIVERSE}
    for f in factors:
        fid, wt, direction = str(f["factor_id"]), float(f["weight"]), float(f.get("direction", 1))
        if "vix_gated_reversal" in fid or "residual_volscaled_reversal20" in fid:
            key, gate = "rev20", .75 if stress else .5
        elif "breadth_gated_relative_trend20" in fid or "breadth_defensive_trend" in fid:
            key, gate = "trend", .8 if stress else 1.0
        elif "downside_sharpe20" in fid:
            key, gate = "sharpe", 1.0
        elif "efficiency_trend_reversal" in fid:
            key, gate = "rev20", .65 if stress else .45
        elif "robust_dispweighted_residual_reversal15" in fid:
            key, gate = "rev15", .65 if stress else .45
        else:
            return
        ranks = cs_rank({s: direction * gate * data[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += wt * (ranks[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .07
        for s in ("BTC", "ETH", "WTI"): score[s] -= .04
    inv = {s: 1.0/data[s]["vol"] for s in UNIVERSE}
    mean_inv = np.mean(list(inv.values()))
    score = {s: score[s] * (.85 + .15*inv[s]/mean_inv) for s in UNIVERSE}
    z = (np.array([score[s] for s in UNIVERSE])-np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-8)
    forecast_returns = {s: float(.01*z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(make_weights(score), forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    _last_decision = stamp

strategy = cross_asset_strategy
if __name__ == "__main__":
    pass

