import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_stamp = None


def cs_rank(vals):
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 0.5) / len(good)
    return out


def weights(scores):
    # Broad, bounded allocation: defensive regime is expressed through assets, not cash.
    a = np.asarray([scores[s] for s in UNIVERSE], dtype=float)
    raw = np.exp(np.clip(2.0 * (a - np.mean(a)), -2.5, 2.5))
    w = 0.02 + 0.70 * raw / raw.sum()
    for _ in range(20):
        mask = w > 0.16
        if not mask.any():
            break
        excess = float(np.sum(w[mask] - 0.16))
        w[mask] = 0.16
        w[~mask] += excess * raw[~mask] / max(float(raw[~mask].sum()), 1e-12)
    w = np.maximum(w, 0.02)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global last_stamp
    try:
        factors = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]
    d, stamp = {}, None
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 100:
            return
        df = df.sort_values("date")
        stamp = str(df.iloc[-2]["date"])
        p = np.asarray(df["close"], dtype=float)[:-1]
        if len(p) < 80 or np.any(~np.isfinite(p)) or np.any(p <= 0):
            return
        r = p[1:] / p[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.008)
        v40 = max(float(np.std(r[-40:])), 0.008)
        t20 = (p[-1] / p[-21] - 1.0) / v20
        t60 = (p[-1] / p[-61] - 1.0) / max(float(np.std(r[-60:])), 0.008)
        down = max(float(np.sqrt(np.mean(np.minimum(r[-20:], 0.0) ** 2))), 0.008)
        breadth = float(np.mean(r[-20:] > 0.0))
        path = float(np.sum(np.abs(r[-20:]))) + 1e-8
        d[s] = {"trend": .70*t20 + .30*breadth,
                "consistency": .50*t20 + .50*t60 + .25*breadth,
                "relative": t20, "reversal": -t20,
                "sharpe": float(np.mean(r[-20:])) / down,
                "efficiency": ((p[-1] / p[-21] - 1.0) / path) / v20,
                "vol": v20}
    if last_stamp is not None:
        try:
            if (np.datetime64(stamp) - np.datetime64(last_stamp)) / np.timedelta64(1, "D") < 14:
                return
        except Exception:
            return
    # VIX is observation-only and is used solely as a stress gate.
    stress = np.mean([x["vol"] for x in d.values()]) > 0.018
    vx = get_index_daily_data(symbol="VIX", days=80)
    if vx is not None and len(vx) > 62:
        x = np.asarray(vx.sort_values("date")["close"], dtype=float)[:-1]
        if np.isfinite(x[-1]):
            stress = stress or x[-1] >= float(np.median(x[-60:]))
    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        fid, wt = str(f["factor_id"]), float(f["weight"])
        if "breadth_defensive_trend" in fid: key, gate = "trend", (.85 if stress else 1.0)
        elif "downside_sharpe20" in fid: key, gate = "sharpe", 1.0
        elif "trend_consistency_volscaled" in fid: key, gate = "consistency", 1.0
        elif "breadth_gated_relative_trend20_vol40" in fid: key, gate = "relative", (.80 if stress else 1.0)
        elif "residual_volscaled_reversal15" in fid: key, gate = "reversal", (.35 if stress else .60)
        elif "vix_gated_reversal20" in fid: key, gate = "reversal", (.25 if stress else .80)
        elif "beta_residual_reversal20" in fid: key, gate = "reversal", (.20 if stress else .50)
        else: return
        ranks = cs_rank({s: gate * float(f.get("direction", 1)) * d[s][key] for s in UNIVERSE})
        for s in UNIVERSE:
            score[s] += wt * (ranks[s] - .5)
    if stress:
        for s in DEFENSIVE: score[s] += .10
        for s in ("BTC", "ETH", "WTI"): score[s] -= .06
    inv = {s: 1.0 / d[s]["vol"] for s in UNIVERSE}
    avg = float(np.mean(list(inv.values())))
    score = {s: score[s] * (.88 + .12 * inv[s] / avg) for s in UNIVERSE}
    z = (np.asarray([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))) / max(float(np.std(list(score.values()))), 1e-8)
    forecast_returns = {s: float(.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(weights(score), forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_stamp = stamp

strategy = cross_asset_strategy
if __name__ == "__main__":
    pass

