DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_last_stamp = None


def rank_cs(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    result = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        result[s] = (i + 0.5) / len(valid)
    return result


def make_weights(scores):
    # 15-name, long-only, full-investment portfolio; no cash sleeve.
    raw = np.exp(np.clip(2.0 * (np.array([scores[s] for s in UNIVERSE]) - np.mean(list(scores.values()))), -2.5, 2.5))
    w = 0.02 + 0.70 * raw / raw.sum()
    for _ in range(20):
